mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  vec3 q = p;
  q.xz = rot(q.y * 0.6 + time * 0.3) * q.xz;
  float spire = max(abs(q.x), abs(q.z)) - (0.4 - q.y * 0.15);
  spire = max(spire, abs(p.y) - 2.5);
  // Orbiting spheres
  float ang = time * 1.2;
  vec3 s1 = p - vec3(cos(ang) * 1.2, sin(ang * 0.7), sin(ang) * 1.2);
  float orb = length(s1) - 0.15;
  return min(spire, orb);
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.5, -4.2);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 10.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.03, 0.01, 0.05);
  if (t < 10.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.005, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(-1.0, 2.0, -1.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 40.0);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 3.0);
    col = vec3(0.05, 0.02, 0.08) + diff * vec3(0.8, 0.4, 0.1) + spec * vec3(1.0, 0.9, 0.5) + rim * vec3(1.0, 0.2, 0.4);
  }
  ret = col;
}
